      "path": "formal/Admission.bend",
      "content": "import Base
import ./Model.bend as M

# Lift a decision after removing one unit from both inputs.
# Rejection restores the removed balance unit; success restores the grant unit.
def lift(r: M.Response) -> M.Response:
  match r:
    case Response{False{}, g, b}:
      Response{False{}, g, 1n+b}
    case Response{True{}, g, b}:
      Response{True{}, 1n+g, b}

# Internal subtraction worker accepts zero. Public admission rejects zero.
def take(b: Nat, n: Nat) -> M.Response:
  match b n:
    case 0n 0n:
      Response{True{}, 0n, 0n}
    case 0n 1n+p:
      Response{False{}, 0n, 0n}
    case 1n+bp 0n:
      Response{True{}, 0n, 1n+bp}
    case 1n+bp 1n+np:
      lift(take(bp, np))

def admission(+b: Nat, a: M.Amount) -> M.Response:
  match a:
    case Nonneg{0n}:
      Response{False{}, 0n, b}
    case Nonneg{1n+p}:
      take(b, 1n+p)
    case Neg{p}:
      Response{False{}, 0n, b}
"
